package com.GuildSpamFilter;

import org.junit.Before;
import org.junit.Test;

import static org.mockito.Mockito.when;

public class PvmFiltersTest extends FilterTestBase
{
    private static final String TWISTED_BOW_RAID_DROP = "Biceps Btw received special loot from a raid: Twisted bow (1,500,000,000 coins).";
    private static final String SCROLL_RAID_DROP = "Biceps Btw received special loot from a raid: Dexterous prayer scroll (20,000,000 coins).";

    private static final String WHIP_DROP = "Biceps Btw received a drop: Abyssal whip (1,500,000 coins).";
    private static final String BONES_DROP = "Biceps Btw received a drop: Dragon bones (2,500 coins).";

    @Before
    public void setGrandExchangePrices()
    {
        // The raid loot filter looks up the item's price instead of reading it from the broadcast
        setPrice("Twisted bow", 1_500_000_000L);
        setPrice("Dexterous prayer scroll", 20_000_000L);
        setPrice("Scythe of vitur (uncharged)", 1_000_000_000L);
        setPrice("Metamorphic dust", 5_000_000L);
    }

    private void setPrice(String itemName, long price)
    {
        when(itemManager.getItemPrice(collectionLog.itemId(itemName))).thenReturn(price);
    }

    // Raid loot

    @Test
    public void hidesEveryRaidDropWithTheDefaultThreshold()
    {
        when(config.filterRaidDrop()).thenReturn(true);

        assertHidden(TWISTED_BOW_RAID_DROP);
        assertHidden(SCROLL_RAID_DROP);
    }

    @Test
    public void raidLootThresholdKeepsItemsWorthThatMuchOrMore()
    {
        when(config.filterRaidDrop()).thenReturn(true);
        when(config.raidLootGpThreshold()).thenReturn(1_000_000_000);

        assertShown(TWISTED_BOW_RAID_DROP);
        assertHidden(SCROLL_RAID_DROP);
    }

    @Test
    public void handlesRaidItemNamesWithBrackets()
    {
        when(config.filterRaidDrop()).thenReturn(true);
        when(config.raidLootGpThreshold()).thenReturn(1_200_000_000);

        assertHidden("Biceps Btw received special loot from a raid: Scythe of vitur (uncharged) (1,000,000,000 coins).");
    }

    @Test
    public void readsRaidLootWithoutACoinValue()
    {
        // Raid broadcasts haven't always included the coin value
        when(config.filterRaidDrop()).thenReturn(true);
        when(config.raidLootGpThreshold()).thenReturn(2_000_000_000);

        assertHidden("Biceps Btw received special loot from a raid: Twisted bow.");
        assertHidden("Biceps Btw received special loot from a raid: Scythe of vitur (uncharged).");
    }

    @Test
    public void coversEveryItemOnTheCollectionLogRaidsTab()
    {
        when(config.filterRaidDrop()).thenReturn(true);
        when(config.raidLootGpThreshold()).thenReturn(1_000_000_000);

        assertHidden("Biceps Btw received special loot from a raid: Metamorphic dust (5,000,000 coins).");
    }

    @Test
    public void leavesItemsFromOtherCollectionLogTabsAlone()
    {
        when(config.filterRaidDrop()).thenReturn(true);

        assertShown("Biceps Btw received special loot from a raid: Abyssal whip (1,500,000 coins).");
    }

    @Test
    public void usesTheCurrentPriceWhenTheBroadcastArrives()
    {
        when(config.filterRaidDrop()).thenReturn(true);
        when(config.raidLootGpThreshold()).thenReturn(1_000_000_000);

        setPrice("Twisted bow", 900_000_000L);
        assertHidden(TWISTED_BOW_RAID_DROP);

        setPrice("Twisted bow", 1_100_000_000L);
        assertShown(TWISTED_BOW_RAID_DROP);
    }

    // Regular and rare drops

    @Test
    public void hidesEveryDropWithTheDefaultThreshold()
    {
        when(config.filterRegularDrops()).thenReturn(true);

        assertHidden(WHIP_DROP);
        assertHidden(BONES_DROP);
    }

    @Test
    public void lootThresholdKeepsDropsWorthThatMuchOrMore()
    {
        when(config.filterRegularDrops()).thenReturn(true);
        when(config.lootGpThreshold()).thenReturn(1_000_000);

        assertShown(WHIP_DROP);
        assertHidden(BONES_DROP);
    }

    @Test
    public void handlesDropNamesWithBrackets()
    {
        String onyxBolts = "Biceps Btw received a drop: 10 x Onyx bolts (e) (1,234,567 coins).";
        when(config.filterRegularDrops()).thenReturn(true);

        when(config.lootGpThreshold()).thenReturn(1_000_000);
        assertShown(onyxBolts);

        when(config.lootGpThreshold()).thenReturn(2_000_000);
        assertHidden(onyxBolts);
    }

    @Test
    public void hidesDropsWithoutAValue()
    {
        when(config.filterRegularDrops()).thenReturn(true);
        when(config.lootGpThreshold()).thenReturn(1_000_000);

        assertHidden("Biceps Btw received a drop: Onyx bolts (e).");
    }

    @Test
    public void hidesRareDrops()
    {
        when(config.filterRareDrops()).thenReturn(true);

        assertHidden("Biceps Btw received a rare drop: Dragon warhammer.");
    }
}

package com.GuildSpamFilter;

import com.GuildSpamFilter.Handlers.CollectionLogHandler;
import com.GuildSpamFilter.Models.CollectionLogItem;
import com.GuildSpamFilter.Models.CollectionLogPage;
import com.GuildSpamFilter.Models.CollectionLogTab;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class CollectionLogHandlerTest
{
    private FakeCollectionLog collectionLog;
    private ArrayList<CollectionLogTab> tabs;

    @Before
    public void readCollectionLog()
    {
        Client client = mock(Client.class);
        collectionLog = new FakeCollectionLog()
                .tab("Bosses")
                .page("Abyssal Sire", "Abyssal orphan", "Abyssal whip")
                .page("Kraken", "Pet kraken", "Trident of the seas (full)")
                .tab("Raids").page("Chambers of Xeric", "Olmlet", "Twisted bow")
                .tab("Clues").page("Hard Treasure Trails", "3rd age amulet")
                .tab("Minigames").page("Barbarian Assault", "Fighter hat")
                .tab("Other")
                .page("Aerial Fishing", "Golden tench")
                .page("All Pets", "Pet kraken", "Olmlet");
        collectionLog.installOn(client);

        tabs = new CollectionLogHandler().readData(client);
    }

    @Test
    public void readsTheTabsInGameOrderUnderTheirConstantNames()
    {
        List<String> names = new ArrayList<>();
        for (CollectionLogTab tab : tabs)
        {
            names.add(tab.name);
        }

        // The fake collection log spells out the game's names, so a mistyped constant fails here
        assertEquals(Arrays.asList(CollectionLogTab.BOSSES, CollectionLogTab.RAIDS, CollectionLogTab.CLUES,
                CollectionLogTab.MINIGAMES, CollectionLogTab.OTHER), names);
    }

    @Test
    public void readsEachPageWithItsItems()
    {
        List<CollectionLogPage> bossPages = tab("Bosses").pages;

        assertEquals(2, bossPages.size());
        assertEquals("Abyssal Sire", bossPages.get(0).name);
        assertEquals(Arrays.asList("Abyssal orphan", "Abyssal whip"), itemNames(bossPages.get(0)));
        assertEquals("Kraken", bossPages.get(1).name);
        assertEquals(Arrays.asList("Pet kraken", "Trident of the seas (full)"), itemNames(bossPages.get(1)));
    }

    @Test
    public void keepsEachItemsIdFromTheGame()
    {
        CollectionLogItem whip = tab("Bosses").pages.get(0).items.get(1);

        assertEquals("Abyssal whip", whip.name);
        assertEquals(collectionLog.itemId("Abyssal whip"), whip.id);
    }

    @Test
    public void collectsEveryItemInATabInLowercase()
    {
        CollectionLogTab bosses = tab("Bosses");

        assertEquals(4, bosses.lowercaseItemNames.size());
        assertTrue(bosses.lowercaseItemNames.contains("abyssal whip"));
        assertTrue(bosses.lowercaseItemNames.contains("trident of the seas (full)"));
        assertFalse(bosses.lowercaseItemNames.contains("Abyssal whip"));
    }

    @Test
    public void keepsItemsInEveryTabTheyAppearIn()
    {
        assertTrue(tab("Bosses").lowercaseItemNames.contains("pet kraken"));
        assertTrue(tab("Other").lowercaseItemNames.contains("pet kraken"));
        assertTrue(tab("Raids").lowercaseItemNames.contains("olmlet"));
        assertTrue(tab("Other").lowercaseItemNames.contains("olmlet"));
    }

    private static List<String> itemNames(CollectionLogPage page)
    {
        List<String> names = new ArrayList<>();
        for (CollectionLogItem item : page.items)
        {
            names.add(item.name);
        }

        return names;
    }

    private CollectionLogTab tab(String name)
    {
        for (CollectionLogTab tab : tabs)
        {
            if (tab.name.equals(name))
            {
                return tab;
            }
        }

        throw new AssertionError("No collection log tab named " + name);
    }
}

package com.GuildSpamFilter;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ItemComposition;
import net.runelite.api.StructComposition;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Builds a collection log in a mocked client's game cache, laid out the way the real game stores it:
 * enum 2102 lists the tab structs, each tab struct has a name (param 682) and an enum of page structs (param 683),
 * and each page struct has a name (param 689) and an enum of item ids (param 690).
 */
class FakeCollectionLog
{
    private final Map<String, Map<String, String[]>> tabs = new LinkedHashMap<>();
    private final Map<String, Integer> itemIds = new HashMap<>();
    private Map<String, String[]> currentTab;
    private int nextId = 1_000_000;

    FakeCollectionLog tab(String name)
    {
        currentTab = new LinkedHashMap<>();
        tabs.put(name, currentTab);
        return this;
    }

    FakeCollectionLog page(String name, String... itemNames)
    {
        currentTab.put(name, itemNames);
        return this;
    }

    void installOn(Client client)
    {
        int[] tabStructIds = new int[tabs.size()];
        int tabIndex = 0;
        for (Map.Entry<String, Map<String, String[]>> tab : tabs.entrySet())
        {
            int[] pageStructIds = new int[tab.getValue().size()];
            int pageIndex = 0;
            for (Map.Entry<String, String[]> page : tab.getValue().entrySet())
            {
                int[] pageItemIds = new int[page.getValue().length];
                for (int i = 0; i < pageItemIds.length; i++)
                {
                    String itemName = page.getValue()[i];
                    pageItemIds[i] = nextId++;
                    itemIds.putIfAbsent(itemName, pageItemIds[i]);
                    ItemComposition item = mock(ItemComposition.class);
                    when(item.getName()).thenReturn(itemName);
                    when(client.getItemDefinition(pageItemIds[i])).thenReturn(item);
                }

                int itemsEnumId = addEnum(client, nextId++, pageItemIds);
                pageStructIds[pageIndex++] = addStruct(client, 689, page.getKey(), 690, itemsEnumId);
            }

            int pagesEnumId = addEnum(client, nextId++, pageStructIds);
            tabStructIds[tabIndex++] = addStruct(client, 682, tab.getKey(), 683, pagesEnumId);
        }

        addEnum(client, 2102, tabStructIds);
    }

    /** The item id given to an item name, available after {@link #installOn}. */
    int itemId(String itemName)
    {
        Integer itemId = itemIds.get(itemName);
        if (itemId == null)
        {
            throw new IllegalArgumentException("No item named " + itemName + " in the fake collection log");
        }

        return itemId;
    }

    private static int addEnum(Client client, int enumId, int[] values)
    {
        EnumComposition enumComposition = mock(EnumComposition.class);
        when(enumComposition.getIntVals()).thenReturn(values);
        when(client.getEnum(enumId)).thenReturn(enumComposition);
        return enumId;
    }

    private int addStruct(Client client, int nameParamId, String name, int enumParamId, int enumId)
    {
        int structId = nextId++;
        StructComposition struct = mock(StructComposition.class);
        when(struct.getStringValue(nameParamId)).thenReturn(name);
        when(struct.getIntValue(enumParamId)).thenReturn(enumId);
        when(client.getStructComposition(structId)).thenReturn(struct);
        return structId;
    }
}

package com.GuildSpamFilter;

import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ScriptCallbackEvent;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MessageHandlingTest extends FilterTestBase
{
    private static final String WHIP_DROP = "Biceps Btw received a drop: Abyssal whip (1,500,000 coins).";

    private static final String[] ONE_OF_EACH_BROADCAST = {
            "Biceps Btw has achieved a new Vorkath personal best: 1:05.40",
            "Biceps Btw has a funny feeling like they're being followed: Vorki at 50 killcount.",
            "Store Biceps has been invited into the clan by Biceps Btw.",
            "Biceps Btw has expelled Store Biceps from the clan.",
            "Biceps Btw has completed a quest: Dragon Slayer II",
            "Biceps Btw has completed the Hard Ardougne diary.",
            "Biceps Btw has unlocked the Elite tier of rewards from Combat Achievements!",
            "Biceps Btw has completed an Elite combat task: Perfect Zulrah.",
            "Biceps Btw has died and lost their hardcore ironman status!",
            "Biceps Btw has reached combat level 100.",
            "To talk in your clan's channel, start each line of chat with // or /c.",
            "Biceps Btw received a new collection log item: Abyssal whip (812/1666)",
            "Biceps Btw has reached Fishing level 90.",
            "Biceps Btw has reached 50,000,000 XP in Fishing.",
            "Biceps Btw has reached a total level of 2000.",
            "Biceps Btw has reached the highest possible total level of 2376.",
            "Biceps Btw received special loot from a raid: Twisted bow (1,500,000,000 coins).",
            "Biceps Btw received a drop: Abyssal whip (1,500,000 coins).",
            "Biceps Btw received a rare drop: Dragon warhammer.",
            "Biceps Btw has defeated Store Biceps and received (1,234,567 coins) worth of loot!",
            "Biceps Btw has been defeated by Store Biceps and lost (1,234,567 coins) worth of loot.",
            "<img=22>Biceps Btw has unlocked the Tier 3 relic.",
    };

    @Test
    public void nothingIsHiddenUntilAFilterIsTurnedOn()
    {
        for (String broadcast : ONE_OF_EACH_BROADCAST)
        {
            assertShown(broadcast);
        }
    }

    @Test
    public void messagesTypedByClanmatesAreNeverHidden()
    {
        setCustomFilters("whip");

        assertFalse(isHidden("I just got an abyssal whip!", ChatMessageType.CLAN_CHAT));
    }

    @Test
    public void ignoresOtherChatScriptEvents()
    {
        ScriptCallbackEvent event = new ScriptCallbackEvent();
        event.setEventName("someOtherEvent");
        plugin.onScriptCallbackEvent(event);

        verify(client, never()).getIntStack();
    }

    @Test
    public void startingThePluginRefiltersChat()
    {
        assertChatWasRefilteredOnTheClientThread();
    }

    @Test
    public void stoppingThePluginRefiltersChat()
    {
        clearInvocations(clientThread, client);

        plugin.shutDown();

        assertChatWasRefilteredOnTheClientThread();
    }

    @Test
    public void changingASettingRefiltersChat()
    {
        clearInvocations(clientThread, client);

        changeSetting("filterPets");

        assertChatWasRefilteredOnTheClientThread();
    }

    @Test
    public void ignoresSettingsChangedByOtherPlugins()
    {
        clearInvocations(clientThread, client);
        when(config.customFilters()).thenReturn("whip");

        changeSetting("someotherplugin", "customFilters");

        verify(clientThread, never()).invoke(any(Runnable.class));
        verify(client, never()).refreshChat();
        assertShown(WHIP_DROP);
    }

    @Test
    public void updatesSettingListsOnTheClientThread()
    {
        // Hold back client thread work to see what happens before it runs
        doNothing().when(clientThread).invoke(any(Runnable.class));
        clearInvocations(clientThread);

        setCustomFilters("whip");
        assertShown(WHIP_DROP);

        ArgumentCaptor<Runnable> clientThreadTask = ArgumentCaptor.forClass(Runnable.class);
        verify(clientThread).invoke(clientThreadTask.capture());
        clientThreadTask.getValue().run();
        assertHidden(WHIP_DROP);
    }

    @Test
    public void showsBroadcastsItCannotReadAndWarns()
    {
        when(config.filterPets()).thenThrow(new IllegalStateException("unexpected broadcast"));

        assertShown(WHIP_DROP);
        assertWarned("Couldn't check broadcast \"" + WHIP_DROP + "\"");
    }

    private void assertChatWasRefilteredOnTheClientThread()
    {
        verify(clientThread).invoke(any(Runnable.class));
        verify(client).refreshChat();
    }
}

package com.GuildSpamFilter;

import org.junit.Test;

import static org.mockito.Mockito.when;

public class SkillingFiltersTest extends FilterTestBase
{
    // Level-up wording not yet checked against a real in-game broadcast
    private static final String FISHING_70 = "Biceps Btw has reached Fishing level 70.";
    private static final String FISHING_90 = "Biceps Btw has reached Fishing level 90.";

    private static final String MAX_TOTAL = "Biceps Btw has reached the highest possible total level of 2376.";

    // Level-ups

    @Test
    public void hidesEveryLevelUpWithTheDefaultThreshold()
    {
        when(config.filterLevelUp()).thenReturn(true);

        assertHidden(FISHING_70);
        assertHidden(FISHING_90);
    }

    @Test
    public void levelUpThresholdKeepsThatLevelAndHigher()
    {
        when(config.filterLevelUp()).thenReturn(true);
        when(config.levelThreshold()).thenReturn(80);

        assertHidden(FISHING_70);
        assertShown(FISHING_90);
    }

    @Test
    public void levelUpFilterLeavesTotalAndCombatLevelsAlone()
    {
        when(config.filterLevelUp()).thenReturn(true);

        assertShown("Biceps Btw has reached a total level of 2000.");
        assertShown("Biceps Btw has reached combat level 100.");
    }

    // XP milestones

    @Test
    public void hidesEveryXpMilestoneWithTheDefaultThreshold()
    {
        when(config.filterXpMilestone()).thenReturn(true);

        assertHidden("Biceps Btw has reached 200,000,000 XP in Fishing.");
    }

    @Test
    public void xpMilestoneThresholdKeepsThatAmountAndMore()
    {
        when(config.filterXpMilestone()).thenReturn(true);
        when(config.xpMilestoneThreshold()).thenReturn(100_000_000);

        assertHidden("Biceps Btw has reached 50,000,000 XP in Fishing.");
        assertShown("Biceps Btw has reached 100,000,000 XP in Fishing.");
        assertShown("Biceps Btw has reached 200,000,000 XP in Fishing.");
    }

    // Total level

    @Test
    public void totalLevelThresholdKeepsThatLevelAndHigher()
    {
        when(config.filterTotalLevelMilestone()).thenReturn(true);
        when(config.totalLevelThreshold()).thenReturn(2000);

        assertHidden("Biceps Btw has reached a total level of 1900.");
        assertShown("Biceps Btw has reached a total level of 2000.");
    }

    @Test
    public void readsTotalLevelsWithAThousandsSeparator()
    {
        when(config.filterTotalLevelMilestone()).thenReturn(true);
        when(config.totalLevelThreshold()).thenReturn(2000);

        assertHidden("Biceps Btw has reached a total level of 1,900.");
        assertShown("Biceps Btw has reached a total level of 2,000.");
    }

    @Test
    public void hidesMaxTotalLevel()
    {
        when(config.filterMaxTotal()).thenReturn(true);

        assertHidden(MAX_TOTAL);
    }

    @Test
    public void totalLevelFilterLeavesMaxTotalAlone()
    {
        when(config.filterTotalLevelMilestone()).thenReturn(true);

        assertShown(MAX_TOTAL);
    }
}

